import collections, re, subprocess, sys
EDITABLE = ['rust/crates/agent/src/dto/mod.rs', 'rust/crates/indexer/src/orchestrator.rs', 'rust/crates/repo-index/src/lib.rs', 'rust/crates/repo-index/src/compose.rs', 'rust/crates/daemon-runtime/src/lib.rs', 'rust/crates/daemon-runtime/src/state.rs', 'rust/crates/daemon-runtime/src/dispatch.rs', 'rust/crates/daemon-runtime/src/orient_additive_fields.rs', 'rust/crates/rgr/src/presentation/mod.rs', 'rust/crates/rgr/src/presentation/orient_types.rs', 'rust/crates/rgr/src/presentation/orient.rs', 'rust/crates/rgr/src/presentation/check.rs', 'rust/crates/rgr/src/presentation/orient_tests.rs', 'rust/crates/rgr/src/commands/orient.rs']
TEST_ATTR = re.compile(r'^\s*#\[test\]\s*$')
MOD_DECL = re.compile(r'^\s*(pub(\([a-z]+\))?\s+)?mod\s+\w+\s*[;{]')
CFG_TEST = re.compile(r'^\s*#\[cfg\(test\)\]\s*$')
def body_end(s, i):
    depth, n = 0, len(s)
    while i < n:
        c = s[i]
        if s.startswith('//', i):
            j = s.find('\n', i); i = n if j < 0 else j; continue
        if s.startswith('/*', i):
            j = s.find('*/', i + 2); i = n if j < 0 else j + 2; continue
        m = re.match(r'b?r(#*)"', s[i:i + 40])
        if m and (i == 0 or not (s[i - 1].isalnum() or s[i - 1] == '_')):
            close = '"' + m.group(1); j = s.find(close, i + m.end()); i = n if j < 0 else j + len(close); continue
        if c == '"':
            i += 1
            while i < n and s[i] != '"':
                i += 2 if s[i] == '\\' else 1
            i += 1; continue
        if c == "'":
            if i + 1 < n and s[i + 1] == '\\':
                j = s.find("'", i + 2); i = n if j < 0 else j + 1; continue
            if i + 2 < n and s[i + 2] == "'":
                i += 3; continue
            i += 1; continue
        if c == '{':
            depth += 1
        elif c == '}':
            depth -= 1
            if depth == 0:
                return i + 1
        i += 1
    raise SystemExit('unbalanced body')
def tests(text):
    lines = text.split('\n'); starts = []; pos = 0
    for l in lines:
        starts.append(pos); pos += len(l) + 1
    out = []
    for k, l in enumerate(lines):
        if not TEST_ATTR.match(l):
            continue
        a = k
        while a > 0 and lines[a - 1].strip().startswith('#['):
            a -= 1
        fn = re.compile(r'\bfn\s+(\w+)').search(text, starts[k])
        if fn is None:
            raise SystemExit('#[test] without fn')
        out.append(text[starts[a]:body_end(text, text.index('{', fn.end()))])
    return out
def guards(text):
    return [l.strip() for l in text.split('\n') if MOD_DECL.match(l) or CFG_TEST.match(l)]
def compare(head, cand):
    missing = collections.Counter(tests(head)) - collections.Counter(tests(cand))
    lost = collections.Counter(guards(head)) - collections.Counter(guards(cand))
    return len(tests(head)), list(missing), list(lost)
def main():
    total, bad = 0, []
    for p in EDITABLE:
        head = subprocess.run(['git', 'show', 'HEAD:' + p], capture_output=True, text=True, check=True).stdout
        cand = open(p, encoding='utf-8').read()
        n, missing, lost = compare(head, cand)
        total += n
        bad += [(p, 'test changed or removed', t.split('\n')[0:3]) for t in missing]
        bad += [(p, 'module or cfg(test) line removed', g) for g in lost]
    for b in bad:
        print('P-TS-04 VIOLATION', b)
    if bad:
        sys.exit(1)
    print('TS-C09 OK', total, 'pre-existing tests in', len(EDITABLE), 'editable files kept by name and body')
if __name__ == '__main__':
    main()
PY
